using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CelestialDewOmenData", menuName = "Data/Battle/Omens System/Omen Data/Austra/CelestialDewOmenData")]
public class CelestialDewOmenData : OmenData
{
	[Header("SafeCrit Omen")]
	[SerializeField]
	private CriticalEffect criticalEffect;

	[Header("SafeCrit Modifiers")]
	[SerializeField]
	private int chanceIncreaseAmount;

	[SerializeField]
	private int multiplierIncreaseAmount;

	private int amountOfCriteriaMatch;

	public int ChanceIncreaseAmount => chanceIncreaseAmount;

	public int MultiplierIncreaseAmount => multiplierIncreaseAmount * amountOfCriteriaMatch;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.ActivateSafeCriticalOmenAction = delegate
		{
			amountOfCriteriaMatch = 0;
			CriticalEffect criticalEffect = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerCriticalGetCriticalEffect();
			if (criticalEffect != null)
			{
				ActionInstance currentActionInstance = ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance;
				if (currentActionInstance != null && currentActionInstance is DiceInstance)
				{
					DiceInstance diceInstance = currentActionInstance as DiceInstance;
					BattleAction battleAction = diceInstance.ActionFace.BattleAction;
					if (diceInstance.Dice.DiceTier == ReferenceSingleton<AssetsReference>.Instance.SafeDieTier || diceInstance.Dice.DiceTier == ReferenceSingleton<AssetsReference>.Instance.HexDieTier || battleAction.name.Contains("RandomPurify") || battleAction.name.Contains("Confuse"))
					{
						criticalEffect.CriticalSafeDie = true;
					}
					if (diceInstance.ActionFace.EnableSecondAction)
					{
						BattleAction battleAction2 = diceInstance.ActionFace.BattleAction;
						if (battleAction2.name.Contains("RandomPurify") || battleAction2.name.Contains("Confuse"))
						{
							criticalEffect.CriticalSafeDie = true;
						}
					}
					if (diceInstance.Dice.DiceTier == ReferenceSingleton<AssetsReference>.Instance.SafeDieTier)
					{
						amountOfCriteriaMatch++;
					}
					if (diceInstance.Dice.DiceTier == ReferenceSingleton<AssetsReference>.Instance.HexDieTier)
					{
						amountOfCriteriaMatch++;
					}
					bool flag = false;
					if (battleAction.name.Contains("RandomPurify"))
					{
						flag = true;
					}
					if (!flag && diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.BattleAction.name.Contains("RandomPurify"))
					{
						flag = true;
					}
					if (flag)
					{
						amountOfCriteriaMatch++;
					}
					bool flag2 = false;
					if (battleAction.name.Contains("Confuse"))
					{
						flag2 = true;
					}
					if (!flag2 && diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.BattleAction.name.Contains("Confuse"))
					{
						flag2 = true;
					}
					if (flag2)
					{
						amountOfCriteriaMatch++;
					}
					bool flag3 = false;
					if (battleAction.name.Contains("RandomConfuse"))
					{
						flag3 = true;
					}
					if (!flag3 && diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.BattleAction.name.Contains("RandomConfuse"))
					{
						flag3 = true;
					}
					if (flag3)
					{
						amountOfCriteriaMatch++;
					}
				}
			}
		};
		ReferenceSingleton<AustraOmensHandler>.Instance.DeactivateSafeCriticalOmenAction = delegate
		{
			amountOfCriteriaMatch = 0;
			criticalEffect.CriticalSafeDie = false;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.ActivateSafeCriticalOmenAction = null;
		ReferenceSingleton<AustraOmensHandler>.Instance.DeactivateSafeCriticalOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(base.omenIDDescription), multiplierIncreaseAmount);
	}
}
